import sys
from itertools import product

data = sys.stdin.read().split()
n, X, Y = int(data[0]), int(data[1]), int(data[2])
a = [int(v) for v in data[3:3 + n]]
best = None
for ch in product(range(3), repeat=n):
    cost = 0
    s = 0
    for i in range(n):
        if ch[i] == 0:
            s += a[i]
        elif ch[i] == 1:
            cost += X
        else:
            cost += Y
            s -= a[i]
    if s <= 0 and (best is None or cost < best):
        best = cost
print(best)

